'use client'
import { createContext, useContext, type HTMLAttributes, type ReactNode } from 'react'
import { PanelLeftClose, PanelLeftOpen } from 'lucide-react'
import { useControllable } from '@/hooks/useControllable'
import { cn } from '@/lib/cn'

// The app's rail: Black with a hairline at its edge, 256px wide. `head` holds the logo or the workspace (56px, over a
// hairline), SidebarLabel names each group in capitals, a SidebarLink per page (the page you are on in White), and
// `foot` the account. `collapsible` adds a button that folds it to 64px of icons (the labels stay for assistive tech);
// it folds at once, no motion, as something pressed many times a day should. `collapsed` with `onCollapsedChange`
// controls it. Other attributes land on the <nav>.
export interface SidebarProps extends Omit<HTMLAttributes<HTMLElement>, 'children'> {
  /** The navigation's name for assistive tech. */
  label?: string
  /** The logo or workspace, at the top. */
  head?: ReactNode
  /** The account, at the foot. */
  foot?: ReactNode
  /** Shows the button that folds it to icons. */
  collapsible?: boolean
  /** Folded to icons (with onCollapsedChange). */
  collapsed?: boolean
  defaultCollapsed?: boolean
  onCollapsedChange?: (collapsed: boolean) => void
  className?: string
  children?: ReactNode
}

/** Whether the sidebar around a link or label is folded to icons. */
export const SidebarContext = createContext(false)
export const useSidebarCollapsed = () => useContext(SidebarContext)

export function Sidebar({ label = 'Main', head, foot, collapsible, collapsed: given, defaultCollapsed = false, onCollapsedChange, className, children, ...rest }: SidebarProps) {
  const [collapsed, setCollapsed] = useControllable(given, defaultCollapsed, onCollapsedChange)
  const Icon = collapsed ? PanelLeftOpen : PanelLeftClose
  return (
    <nav data-ds="sidebar" aria-label={label} data-collapsed={collapsed || undefined} className={cn('flex h-full shrink-0 flex-col border-r border-edge bg-surface', collapsed ? 'w-16' : 'w-rail', className)} {...rest}>
      {(head || collapsible) && (
        <div className={cn('flex h-14 shrink-0 items-center gap-2 border-b border-edge px-3', collapsed ? 'justify-center' : 'justify-between')}>
          {head && !collapsed && <div className="flex min-w-0 flex-1 items-center pl-1">{head}</div>}
          {collapsible && (
            <button type="button" className="inline-flex size-control-md shrink-0 cursor-pointer items-center justify-center rounded-control text-fg-muted transition-[background-color,color] duration-160 ease-standard hover:bg-action-ghost-hover hover:text-fg" aria-label={collapsed ? 'Expand sidebar' : 'Collapse sidebar'} aria-expanded={!collapsed} onClick={() => setCollapsed(!collapsed)}>
              <Icon size={16} strokeWidth={1.5} aria-hidden="true" />
            </button>
          )}
        </div>
      )}
      <SidebarContext.Provider value={collapsed}>
        <div className="flex min-h-0 flex-1 flex-col gap-0.5 overflow-y-auto p-3 fade-y">{children}</div>
      </SidebarContext.Provider>
      {foot && <div className={cn('shrink-0 border-t border-edge p-3', collapsed && 'hidden')}>{foot}</div>}
    </nav>
  )
}

export default Sidebar

'use client'
import type { ReactNode } from 'react'
import { useSidebarCollapsed } from '@/components/ui/Sidebar'

// A group's name in the Sidebar: DM Sans Medium in capitals at 6%, muted, 16px over it. Folded to icons, a hairline
// takes its place and the name stays for assistive tech.
export interface SidebarLabelProps {
  /** The group's name. */
  children?: ReactNode
}

export function SidebarLabel({ children }: SidebarLabelProps) {
  const collapsed = useSidebarCollapsed()
  return (
    <div data-ds="sidebar-label" className="pt-4 pb-2 first:pt-1">
      {collapsed ? <div className="mx-2 border-t border-edge" aria-hidden="true" /> : null}
      <p className={collapsed ? 'sr-only' : 'px-3 type-label text-fg-muted'}>{children}</p>
    </div>
  )
}

export default SidebarLabel

'use client'
import type { AnchorHTMLAttributes, ComponentType, ElementType } from 'react'
import { useSidebarCollapsed } from '@/components/ui/Sidebar'
import { cn } from '@/lib/cn'

// One page in the Sidebar: a 40px row (44px on phones) with its 16px icon, the label and a count at the end, the brand
// corner. The page you are on is White with Black type, as the primary button; the others are soft gray and fill on
// hover. Folded to icons, the row is a 40px square and the label stays for assistive tech. `as` renders a router link
// component instead of an anchor; other props (onClick) land on the link.
export interface SidebarLinkProps extends AnchorHTMLAttributes<HTMLAnchorElement> {
  href?: string
  /** The page you are on. */
  active?: boolean
  /** A Lucide icon. */
  icon?: ComponentType<{ size?: number, strokeWidth?: number, 'aria-hidden'?: boolean | 'true' }>
  /** A count at the end of the row. */
  status?: string
  /** A router link component in place of <a>. */
  as?: ElementType
}

export function SidebarLink({ href, active, icon: Icon, status, as: Link = 'a', className, children, ...rest }: SidebarLinkProps) {
  const collapsed = useSidebarCollapsed()
  return (
    <Link
      data-ds="sidebar-link"
      href={href}
      aria-current={active ? 'page' : undefined}
      className={cn(
        'flex h-row shrink-0 cursor-pointer items-center gap-3 rounded-control type-ui -outline-offset-2 transition-[background-color,color] duration-160 ease-standard max-md:h-control-touch',
        collapsed ? 'w-row justify-center px-0' : 'px-3',
        active ? 'bg-action-primary text-action-primary-fg' : 'text-fg-soft hover:bg-action-ghost-hover hover:text-fg',
        className,
      )}
      {...rest}
    >
      {Icon && <span className={cn('flex shrink-0', active ? 'text-action-primary-fg' : 'text-fg-muted')}><Icon size={16} strokeWidth={1.5} aria-hidden="true" /></span>}
      <span className={collapsed ? 'sr-only' : 'min-w-0 flex-1 truncate'}>{children}</span>
      {status && !collapsed && <span className={cn('type-caption tabular-nums', active ? 'text-action-primary-fg' : 'text-fg-muted')}>{status}</span>}
    </Link>
  )
}

export default SidebarLink

'use client'
import { useCallback, useRef, useState } from 'react'

// Vue's defineModel in React: a value that is controlled when the caller passes it (value + onValueChange, as Radix
// does) and kept inside otherwise (defaultValue). setValue calls onChange either way.
export function useControllable<T>(value: T | undefined, defaultValue: T, onChange?: (value: T) => void) {
	const [inner, setInner] = useState<T>(defaultValue)
	const controlled = value !== undefined
	const current = controlled ? value : inner
	const ref = useRef(onChange)
	ref.current = onChange
	const set = useCallback((next: T) => {
		if (!controlled) setInner(next)
		ref.current?.(next)
	}, [controlled])
	return [current, set] as const
}

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}
